package com.dreamseekers;

import com.dreamseekers.skill.*;
import com.dreamseekers.unit.*;
import com.mojang.authlib.GameProfile;
import com.solegendary.reignofnether.player.*;
import com.solegendary.reignofnether.registrars.*;
import com.solegendary.reignofnether.resources.*;
import com.solegendary.reignofnether.unit.UnitServerEvents;
import com.solegendary.reignofnether.unit.interfaces.Unit;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.*;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.minecraftforge.common.util.FakePlayerFactory;
import net.minecraftforge.gametest.*;
import java.io.File;
import java.util.*;

/** Two real JVM processes and ordinary world save/load; manifest contains expectations, never entity payloads. */
@GameTestHolder("dreamseekers_wind_dash_restart")
@PrefixGameTestTemplate(false)
public final class WindDashSkillRestartGameTests {
    private static final String OWNER="WindDashRestart_Owner",ENEMY="WindDashRestart_Enemy";
    private static final BlockPos ORIGIN=new BlockPos(38912,90,38912);
    private static final File MANIFEST=new File("wind-dash-skill-restart-expectations.nbt");
    private static final UUID PERMANENT=UUID.fromString("d1b3c992-0b95-4f45-bb45-269d085574bb");
    private static final List<String> KEYS=List.of("dashCaster","dashTarget","impactCaster","impactTarget","commandTarget","unusedCaster","freshTarget");

    @GameTest(template="unit_isolation_arena",batch="dreamseekers_wind_dash_restart",timeoutTicks=1500)
    public static void ordinaryRestartKeepsSpentCooldownWithoutReplayingDashKnockbackOrCommand(GameTestHelper h)throws Exception {
        switch(System.getProperty("dreamseekers.wind.dash.test.phase","")){
            case "prepare" -> prepare(h);case "verify" -> verify(h);default -> throw new IllegalArgumentException("Unknown Wind dash restart phase");
        }
    }
    private static void prepare(GameTestHelper h){
        ServerLevel level=h.getLevel();h.assertTrue(!MANIFEST.exists()&&PlayerServerEvents.getRTSPlayer(OWNER)==null&&PlayerServerEvents.getRTSPlayer(ENEMY)==null,"fresh isolated restart world, never overwrite accepted evidence");
        CompoundTag expected=new CompoundTag();expected.putLong("prepareJvmStart",java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime());List<Long> forced=new ArrayList<>();for(int x=2432;x<=2433;x++)for(int z=2432;z<=2433;z++){long key=ChunkPos.asLong(x,z);h.assertTrue(!level.getForcedChunks().contains(key),"not adopting unrelated forced chunks");level.setChunkForced(x,z,true);forced.add(key);}expected.putLongArray("forcedChunks",forced);arena(level);
        for(String name:List.of(OWNER,ENEMY)){PlayerServerEvents.rtsPlayers.add(RTSPlayer.getNewBot(name,DreamseekersMod.DREAMSEEKERS));ResourcesServerEvents.resourcesList.add(new Resources(name,123,234,345,456));}
        Map<String,Mob> units=new LinkedHashMap<>();int[][] places={{4,4},{10,4},{4,14},{10,14},{4,17},{4,24},{10,24}};
        for(int i=0;i<KEYS.size();i++){String key=KEYS.get(i);Mob e=key.endsWith("Caster")?DreamseekersMod.WIND_KNIGHT_UNIT.get().create(level):key.equals("commandTarget")?DreamseekersMod.PINK_SLIME_UNIT.get().create(level):EntityRegistrar.ZOMBIE_UNIT.get().create(level);h.assertTrue(e instanceof Unit,"registered native unit fixture");Unit unit=(Unit)e;unit.setOwnerName(key.endsWith("Target")&&!key.equals("commandTarget")?ENEMY:OWNER);unit.setScenarioRoleIndex(1401+i);e.moveTo(ORIGIN.getX()+places[i][0]+.5,ORIGIN.getY()+1,ORIGIN.getZ()+places[i][1]+.5);e.setNoAi(true);if(e instanceof WindKnightUnit){e.getAttribute(AttributeRegistrar.AGGRO_RANGE.get()).setBaseValue(0);e.getAttribute(AttributeRegistrar.ATTACK_DAMAGE.get()).setBaseValue(10);if(e.getAttribute(Attributes.ATTACK_DAMAGE)!=null)e.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(10);e.getAttribute(AttributeRegistrar.CRITICAL_HIT_CHANCE.get()).setBaseValue(0);}else if(!key.equals("commandTarget"))durable(e);h.assertTrue(level.addFreshEntity(e),"ordinary entity storage accepts fixture");units.put(key,e);expected.putUUID(key,e.getUUID());}
        Mob recipient=units.get("commandTarget");recipient.getAttribute(Attributes.MOVEMENT_SPEED).addPermanentModifier(new AttributeModifier(PERMANENT,"permanent restart movement research",.02,AttributeModifier.Operation.ADDITION));recipient.getAttribute(AttributeRegistrar.ATTACK_DAMAGE.get()).addPermanentModifier(new AttributeModifier(PERMANENT,"permanent restart damage research",2,AttributeModifier.Operation.ADDITION));long[] groundAt={Long.MIN_VALUE};Vec3[] dashStart={null};
        WindKnightUnit dash=(WindKnightUnit)units.get("dashCaster"),impact=(WindKnightUnit)units.get("impactCaster");
        h.startSequence().thenWaitUntil(()->{for(Mob e:units.values())h.assertTrue(e.tickCount>3&&level.getEntity(e.getId())==e&&level.getEntity(e.getUUID())==e,"genuine ordinary publication before prepare");})
          .thenExecute(()->{for(Mob e:units.values())if(e instanceof WindKnightUnit) e.setNoAi(false);})
          .thenWaitUntil(()->{boolean grounded=true;for(Mob e:units.values())if(e instanceof WindKnightUnit)grounded&=e.onGround()&&level.noCollision(e);if(!grounded){groundAt[0]=Long.MIN_VALUE;h.assertTrue(false,"genuine ground physics before planning");}if(groundAt[0]==Long.MIN_VALUE)groundAt[0]=level.getGameTime();h.assertTrue(level.getGameTime()>groundAt[0],"two distinct stable ground ticks");})
          .thenExecute(()->{System.out.println("WIND_RESTART_PREPARE_READY testTick="+h.getTick()+" entityTicks="+units.values().stream().map(e->e.getId()+":"+e.tickCount).toList());position(units.get("impactTarget"),impact.position().add(1.8,0,0));position(recipient,impact.position().add(0,0,2));dashStart[0]=dash.position();h.assertTrue(cast(level,dash,units.get("dashTarget"))==SkillResult.SUCCESS&&cast(level,impact,units.get("impactTarget"))==SkillResult.SUCCESS,"both are actual paid manual casts");})
          .thenWaitUntil(()->h.assertTrue(WindDash.isActive(dash)&&dash.position().distanceTo(dashStart[0])>.01&&dash.distanceTo(units.get("dashTarget"))>2&&WindDash.knockbackTicks(units.get("impactTarget"))>0&&impact.distanceTo(units.get("impactTarget"))>2.1&&SkillEffects.hasNamedBuff(recipient,WindDash.COMMAND_KEY,BuffKind.MOVEMENT_SPEED),"capture real in-flight dash and unfinished collision knockback with live completed command, outside ordinary idle melee reacquisition"))
          .thenExecute(()->{
              close(h,units.get("dashTarget").getHealth(),200,"in-flight fixture not hit yet");close(h,units.get("impactTarget").getHealth(),185,"impact fixture took genuine fifteen HP");h.assertTrue(SkillEffects.hasNamedBuff(recipient,WindDash.COMMAND_KEY,BuffKind.ATTACK_DAMAGE),"live actual damage command accompanies movement");
              // NoAI only stabilizes the remaining PREPARE process. Wind load legitimately restores AI.
              // Persisted AGGRO_RANGE=0 plus both enemy distances >2 prevent confusing a new legal idle hit with replay.
              for(Mob e:units.values())if(e instanceof WindKnightUnit){e.setNoAi(true);e.setDeltaMovement(Vec3.ZERO);}expected.putLong("snapshotGameTime",level.getGameTime());expected.putInt("activeDashTicks",WindDash.ticksRemaining(dash));expected.putInt("unfinishedKnockbackTicks",WindDash.knockbackTicks(units.get("impactTarget")));expected.putBoolean("liveCommand",true);
              for(var entry:units.entrySet()){Mob e=entry.getValue();Unit unit=(Unit)e;CompoundTag state=new CompoundTag();state.putString("owner",unit.getOwnerName());state.putFloat("health",e.getHealth());state.putInt("scenario",unit.getScenarioRoleIndex());state.putDouble("baseMove",e.getAttribute(Attributes.MOVEMENT_SPEED).getBaseValue());state.putDouble("baseDamage",e.getAttribute(AttributeRegistrar.ATTACK_DAMAGE.get()).getBaseValue());if(e instanceof SkillUnit skill){state.putLong("revision",skill.rts().skills().revision());state.putInt("cooldown",skill.rts().skills().cooldownTicks(UnitSkill.WIND_DASH));}expected.put(entry.getKey()+"State",state);}
              ledger(h);try{NbtIo.writeCompressed(expected,MANIFEST);}catch(Exception e){throw new RuntimeException(e);}System.out.println("DREAMSEEKERS_WIND_RESTART_PREPARED gameTime="+level.getGameTime()+" activeUUID="+dash.getUUID()+" impactUUID="+impact.getUUID()+" commandUUID="+recipient.getUUID()+" activeTicks="+WindDash.ticksRemaining(dash)+" knockbackTicks="+WindDash.knockbackTicks(units.get("impactTarget"))+" dashCooldown="+dash.rts().skills().cooldownTicks(UnitSkill.WIND_DASH));
          }).thenSucceed();
    }
    private static void verify(GameTestHelper h)throws Exception {
        ServerLevel level=h.getLevel();h.assertTrue(MANIFEST.isFile(),"ordinary prepare expectations exist");CompoundTag expected=NbtIo.readCompressed(MANIFEST);h.assertTrue(expected.getLong("prepareJvmStart")!=java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime(),"genuinely distinct JVM process");h.assertTrue(expected.getInt("activeDashTicks")>0&&expected.getInt("unfinishedKnockbackTicks")>0&&expected.getBoolean("liveCommand"),"prepare actually observed all three kinds of live short runtime");for(long key:expected.getLongArray("forcedChunks")){h.assertTrue(level.getForcedChunks().contains(key),"ordinary world save retained owned forced chunks");ChunkPos c=new ChunkPos(key);level.getChunk(c.x,c.z);}Map<String,Mob> units=new LinkedHashMap<>();Vec3[] loadedImpact={null};long[] grounded={Long.MIN_VALUE};
        h.startSequence().thenWaitUntil(()->{for(String key:KEYS){Entity e=level.getEntity(expected.getUUID(key));h.assertTrue(e instanceof Mob mob&&mob instanceof Unit&&mob.tickCount>3&&level.getEntity(e.getId())==e,"ordinary asynchronous UUID restoration: "+key);}})
          .thenExecute(()->{
              System.out.println("WIND_RESTART_VERIFY_READY testTick="+h.getTick()+" entityTicks="+KEYS.stream().map(key->level.getEntity(expected.getUUID(key)).tickCount).toList());
              for(String key:KEYS){Mob e=(Mob)level.getEntity(expected.getUUID(key));units.put(key,e);Unit unit=(Unit)e;CompoundTag state=expected.getCompound(key+"State");h.assertTrue(unit.getOwnerName().equals(state.getString("owner"))&&unit.getScenarioRoleIndex()==state.getInt("scenario"),"real restored owner/scenario: "+key);close(h,e.getHealth(),state.getFloat("health"),"no replayed hit or repair: "+key);h.assertTrue(UnitServerEvents.getAllUnits().stream().filter(u->u.getUUID().equals(e.getUUID())).count()==1,"UUID entered roster exactly once: "+key);h.assertTrue(WindDash.knockbackTicks(e)==0&&!SkillEffects.hasNamedBuff(e,WindDash.COMMAND_KEY,BuffKind.MOVEMENT_SPEED)&&!SkillEffects.hasNamedBuff(e,WindDash.COMMAND_KEY,BuffKind.ATTACK_DAMAGE),"no restored ephemeral knockback or command: "+key);close(h,SkillEffects.bonus(e,BuffKind.MOVEMENT_SPEED),0,"no permanent movement residue: "+key);close(h,SkillEffects.bonus(e,BuffKind.ATTACK_DAMAGE),0,"no permanent damage residue: "+key);close(h,e.getAttribute(Attributes.MOVEMENT_SPEED).getBaseValue(),state.getDouble("baseMove"),"base movement retained: "+key);close(h,e.getAttribute(AttributeRegistrar.ATTACK_DAMAGE.get()).getBaseValue(),state.getDouble("baseDamage"),"base damage retained: "+key);if(e instanceof WindKnightUnit w){h.assertTrue(!WindDash.isActive(w),"no loaded dash path or pending strike");close(h,w.getAttribute(AttributeRegistrar.AGGRO_RANGE.get()).getBaseValue(),0,"real persisted low-aggro fixture prevents a new ordinary hit");}if(e instanceof SkillUnit skill){long expiry=expected.getLong("snapshotGameTime")+state.getInt("cooldown");int remaining=(int)Math.max(0,expiry-level.getGameTime());h.assertTrue(skill.rts().skills().cooldownTicks(UnitSkill.WIND_DASH)==remaining,"absolute cooldown neither refunded nor restarted: "+key+" expected="+remaining+" actual="+skill.rts().skills().cooldownTicks(UnitSkill.WIND_DASH));h.assertTrue(skill.rts().skills().revision()>=state.getLong("revision"),"loaded revision cannot rewind: "+key);}e.setNoAi(true);}
              Mob recipient=units.get("commandTarget");close(h,recipient.getAttributeValue(Attributes.MOVEMENT_SPEED),expected.getCompound("commandTargetState").getDouble("baseMove")+.02,"only true permanent movement research remains");close(h,recipient.getAttributeValue(AttributeRegistrar.ATTACK_DAMAGE.get()),expected.getCompound("commandTargetState").getDouble("baseDamage")+2,"only true permanent damage research remains");h.assertTrue(recipient.getAttribute(Attributes.MOVEMENT_SPEED).getModifier(PERMANENT)!=null&&recipient.getAttribute(AttributeRegistrar.ATTACK_DAMAGE.get()).getModifier(PERMANENT)!=null,"both permanent modifiers survived ordinary save/load");
              // Original unfinished collision segments may legitimately finish during normal prepare shutdown.
              // Therefore compare against the ACTUAL loaded position, never a hand-restored manifest position.
              loadedImpact[0]=units.get("impactTarget").position();ledger(h);
          }).thenIdle(8).thenExecute(()->{h.assertTrue(units.get("impactTarget").position().equals(loadedImpact[0]),"no delayed knockback segment replayed after load");WindKnightUnit spent=(WindKnightUnit)units.get("dashCaster"),fresh=(WindKnightUnit)units.get("unusedCaster");if(spent.rts().skills().cooldownTicks(UnitSkill.WIND_DASH)>0)h.assertTrue(cast(level,spent,units.get("dashTarget"))!=SkillResult.SUCCESS,"spent source cannot obtain free recast after restart");h.assertTrue(fresh.rts().skills().cooldownTicks(UnitSkill.WIND_DASH)==0,"unused caster remains unused");fresh.setNoAi(false);})
          .thenWaitUntil(()->{var fresh=(WindKnightUnit)units.get("unusedCaster");h.assertTrue(fresh.onGround()&&level.noCollision(fresh),"real ground readiness for a genuinely new post-load cast");if(grounded[0]==Long.MIN_VALUE)grounded[0]=level.getGameTime();h.assertTrue(level.getGameTime()>grounded[0],"real two-tick post-load ground readiness");})
          .thenExecute(()->h.assertTrue(cast(level,(WindKnightUnit)units.get("unusedCaster"),units.get("freshTarget"))==SkillResult.SUCCESS,"new authenticated cast works after real restart"))
          .thenWaitUntil(()->h.assertTrue(!WindDash.isActive((WindKnightUnit)units.get("unusedCaster")),"new post-restart dash genuinely completes"))
          .thenExecute(()->{close(h,units.get("freshTarget").getHealth(),185,"new post-restart runtime performs actual fifteen HP hit");ledger(h);System.out.println("DREAMSEEKERS_WIND_RESTART_UUID_ABSOLUTE_CD_NO_REPLAY_PASS elapsedWorldTicks="+(level.getGameTime()-expected.getLong("snapshotGameTime"))+" spentRemaining="+((SkillUnit)units.get("dashCaster")).rts().skills().cooldownTicks(UnitSkill.WIND_DASH));for(Mob e:units.values())e.discard();PlayerServerEvents.rtsPlayers.removeIf(p->p.name.equals(OWNER)||p.name.equals(ENEMY));ResourcesServerEvents.resourcesList.removeIf(r->r.ownerName.equals(OWNER)||r.ownerName.equals(ENEMY));for(long key:expected.getLongArray("forcedChunks")){ChunkPos c=new ChunkPos(key);level.setChunkForced(c.x,c.z,false);}}).thenSucceed();
    }
    private static SkillResult cast(ServerLevel level,WindKnightUnit source,LivingEntity target){return SkillService.request(FakePlayerFactory.get(level,new GameProfile(UUID.nameUUIDFromBytes(OWNER.getBytes(java.nio.charset.StandardCharsets.UTF_8)),OWNER)),new SkillRequest(UnitSkill.WIND_DASH,source.getId(),source.getUUID(),source.rts().skills().revision(),target.getId(),target.getUUID()));}
    private static void position(Entity e,Vec3 p){e.moveTo(p.x,p.y,p.z);e.setDeltaMovement(Vec3.ZERO);}
    private static void durable(LivingEntity e){e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);e.setHealth(200);e.getAttribute(Attributes.ARMOR).setBaseValue(0);e.getAttribute(Attributes.ARMOR_TOUGHNESS).setBaseValue(0);e.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(0);for(var a:List.of(AttributeRegistrar.MAGIC_DAMAGE_RESIST.get(),AttributeRegistrar.RANGED_DAMAGE_RESIST.get()))e.getAttribute(a).setBaseValue(0);e.setAbsorptionAmount(0);}
    private static void close(GameTestHelper h,double actual,double expected,String why){h.assertTrue(Math.abs(actual-expected)<.0004,why+": expected="+expected+" actual="+actual);}
    private static void ledger(GameTestHelper h){for(String name:List.of(OWNER,ENEMY)){var r=ResourcesServerEvents.resourcesList.stream().filter(e->e.ownerName.equals(name)).findFirst().orElseThrow();h.assertTrue(r.food==123&&r.wood==234&&r.ore==345&&r.emerald==456,"ordinary skill/restart does not alter global resources: "+name);}}
    private static void arena(ServerLevel level){for(int x=0;x<30;x++)for(int z=0;z<30;z++)level.setBlock(ORIGIN.offset(x,9,z),Blocks.STONE.defaultBlockState(),2);level.getEntitiesOfClass(net.minecraft.world.entity.item.FallingBlockEntity.class,new AABB(ORIGIN.getX(),ORIGIN.getY()+1,ORIGIN.getZ(),ORIGIN.getX()+30,level.getMaxBuildHeight(),ORIGIN.getZ()+30)).forEach(Entity::discard);for(int x=0;x<30;x++)for(int z=0;z<30;z++){level.setBlock(ORIGIN.offset(x,0,z),Blocks.STONE.defaultBlockState(),2);for(int y=1;y<9;y++)level.setBlock(ORIGIN.offset(x,y,z),(x==0||x==29||z==0||z==29?Blocks.STONE:Blocks.AIR).defaultBlockState(),2);}}
}
